public:
    explicit TextShape(std::unique_ptr<TextView> adaptee)
        : adaptee_(std::move(adaptee)) {}
    BoundingBox boundingBox() const override {   // target operation
        const auto ext = adaptee_->getExtent();  // adaptee operation
        return {{ext.x, ext.y}, {ext.x + ext.w, ext.y + ext.h}};
    }
private:
    std::unique_ptr<TextView> adaptee_;          // owned adaptee
};

